{"path": "/opt/data/.hermes/desktop-plugins/custom-placeholders/plugin.js", "content": "/**
 * Custom Placeholder Text Plugin
 * Overrides the default input placeholder strings in the Hermes desktop composer.
 */

import { host } from '@hermes/plugin-sdk'

export default {
  id: 'custom-placeholders',
  name: 'Custom Placeholder Text',

  register(ctx) {
    // Register custom placeholder text that overrides the default English strings
    ctx.i18n.registerAppLocale('en', {
      endonym: 'English',
      translations: {
        assistant: {
          composer: {
            // Override new session placeholders (randomized on each new chat)
            newSessionPlaceholders: [
              'What would you like to work on?',
              'How can I help you today?',
              'What can I do for you?',
              'Ready when you are',
              'What\'s the task?'
            ],

            // Override follow-up placeholders (shown after first message in a conversation)
            followUpPlaceholders: [
              'What else?',
              'Continue here',
              'Next request',
              'Keep going',
              'What now?'
            ]
          }
        }
      }
    })

    console.log('[custom-placeholders] Registered custom placeholder text')
  }
}
"}

